// ---------------------------------------------------------------------------
// PRINTNAME — Category B: Accessor Inline Function
//
// Pattern P1: Extract the print-name CHARSXP from a SYMSXP node.
// Location: rpart_callback.c:24
//
//   error(_("variable '%s' not found"), CHAR(PRINTNAME(sym)));
//
// Original Rinternals.h declaration (line 364, under "Symbol Access Functions"):
//   SEXP (PRINTNAME)(SEXP x);
//
// Fake mechanism: In the real R runtime a SYMSXP node carries a dedicated
// print-name slot (a CHARSXP pointer packed into the node header word).  In the
// fake SEXPREC (defined in INTSXP.h / SEXP.h), each node has a single void*
// data field.  For a SYMSXP constructed by install() (Category E stub), data
// holds a pointer to the child CHARSXP node created by mkChar(name).
// PRINTNAME(s) therefore returns static_cast<SEXP>(s->data).
//
// Defensive guard: if s is null, not a SYMSXP, or has data==NULL (e.g., for
// the R_UnboundValue sentinel whose data is NULL), the fallback returns
// R_NilValue.  R_CHAR on R_NilValue returns NULL (cast of NULL void*); this
// path only fires on the diagnostic error path and is never reached in the
// normal rpart call flow because sym always originates from install().
//
// Call chain for rpart_callback.c:24:
//   sym->type == SYMSXP, sym->data == &charsxp_node
//   PRINTNAME(sym)       -> static_cast<SEXP>(sym->data) == &charsxp_node
//   CHAR(charsxp_node)   -> R_CHAR(charsxp_node)
//                        -> static_cast<const char*>(charsxp_node->data)
//                        -> e.g. "yback"
//   error("variable '%s' not found", "yback")
//                        -> Rf_error(...) -> throw RError("variable 'yback' not found")
//
// Contract with install(): any SYMSXP passed to PRINTNAME must be constructed
// with its data field pointing to a valid CHARSXP node produced by mkChar().
// The install() stub (Category E, separate guide) is the canonical constructor.
// PRINTNAME does not enforce this contract; it trusts the caller.
//
// NOTE: The PRIMARY definition lives in SEXP.h under FAKE_PRINTNAME_DEFINED.
// The block below is a guarded fallback for translation units that include
// PRINTNAME.h without SEXP.h having been included first.  In practice, the
// #include "SEXP.h" directive above fires first, making this fallback a no-op.
// It is retained so PRINTNAME.h is fully self-contained when included alone.
// ---------------------------------------------------------------------------
#ifndef FAKE_PRINTNAME_DEFINED
#define FAKE_PRINTNAME_DEFINED

// PRINTNAME — extracts the print-name CHARSXP from a SYMSXP node.
//
// The implementation reads s->data, which for a correctly constructed fake
// SYMSXP (produced by install()) points to the child CHARSXP node created
// by mkChar().  The type guard (s->type == SYMSXP) and null check on data
// are defensive measures absent from the real R implementation, which trusts
// that callers always pass a valid SYMSXP.
//
// For the R_UnboundValue sentinel (type=SYMSXP, data=NULL): the check
// s->data is false, so R_NilValue is returned as the fallback.  R_CHAR
// applied to R_NilValue returns NULL (a null const char*).  This situation
// cannot arise in practice because CHAR(PRINTNAME(sym)) is only reached
// after compat_getVar's guard confirms val != R_UnboundValue, and sym
// itself always comes from install() which sets data to a valid CHARSXP.
inline SEXP PRINTNAME(SEXP s) {
    if (s && s->type == SYMSXP && s->data)
        return static_cast<SEXP>(s->data);
    return R_NilValue;
}

#endif // FAKE_PRINTNAME_DEFINED

